import{_ as t}from"./chunks/filtrace.B2Bh4beK.js";import{_ as e}from"./chunks/01.DFo7dAfa.js";import{_ as a,o as r,c as n,aa as s}from"./chunks/framework.BAs_AphD.js";const l="/buildary-help-preview/academy/img/okno-spp/01.webp",p="/buildary-help-preview/academy/img/schvalovani-spp/05.webp",g=JSON.parse('{"title":"Okno soupisu","description":"","frontmatter":{"title":"Okno soupisu","wiki":"cs:performedworks:application_window"},"headers":[],"relativePath":"performedworks/application_window.md","filePath":"performedworks/application_window.md","lastUpdated":1794209661000}'),d={name:"performedworks/application_window.md"};function i(v,o,u,k,h,m){return r(),n("div",null,[...o[0]||(o[0]=[s('<h1 id="okno-soupisu" tabindex="-1">Okno soupisu <a class="header-anchor" href="#okno-soupisu" aria-label="Permalink to &quot;Okno soupisu&quot;">​</a></h1><p>V okně soupisu zadáváte a schvalujete čerpání položek rozpočtu za vybrané období. Stejné okno slouží pro soupisy mezi stavebníkem a zhotovitelem (<strong>SPP Zhotovitele</strong>) i mezi zhotovitelem a podzhotovitelem (<strong>SPP Podzhotovitele</strong>).</p><p>Krok za krokem: <a href="/buildary-help-preview/akademie/okno-spp">Zadat provedené množství do soupisu</a> a <a href="/buildary-help-preview/akademie/spp-podzhotovitele">Vést soupisy s podzhotoviteli</a> v Akademii.</p><figure class="shot" style="--w:760px;"><img src="'+l+'" alt="Okno SPP Zhotovitele s obdobím Říjen 2026, výběrem stavebníka a zhotovitele, tlačítky Protokoly a Odeslat na schválení a tabulkou položek rozpočtu" loading="lazy"></figure><p>Okno otevřete v levém panelu: <strong>SPP Zhotovitele</strong> nebo <strong>SPP Podzhotovitele</strong>. Které sloupce můžete upravovat a která tlačítka vidíte, závisí na vaší firmě a roli v projektovém týmu – viz <a href="/buildary-help-preview/performedworks/competences">Kompetence pro soupisy</a>.</p><h2 id="zahlavi-okna" tabindex="-1">Záhlaví okna <a class="header-anchor" href="#zahlavi-okna" aria-label="Permalink to &quot;Záhlaví okna&quot;">​</a></h2><p>Údaje v záhlaví určují, se kterým soupisem pracujete: za jaké období a mezi kterými dvěma firmami.</p><table tabindex="0"><thead><tr><th>Prvek</th><th>Význam</th></tr></thead><tbody><tr><td><strong>Období</strong> (například <strong>Říjen 2026</strong>)</td><td>Vyberte období soupisu. Jak období založit, popisuje <a href="/buildary-help-preview/performedworks/period">Období soupisů</a>.</td></tr><tr><td><strong>Stavebník</strong> a <strong>Zhotovitel</strong> (v SPP Podzhotovitele <strong>Zhotovitel</strong> a <strong>Podzhotovitel</strong>)</td><td>Dvojice firem, mezi kterými soupis probíhá. Za svou stranu vidíte jen firmu, ke které jste v projektovém týmu přiřazeni. Za druhou stranu si vyberete ze všech firem, které jsou v rozpočtu stavby.</td></tr><tr><td><strong>Protokoly</strong></td><td>Otevře seznam zjišťovacích protokolů vybrané dvojice firem – viz <a href="/buildary-help-preview/performedworks/output_methods">Výstupy soupisů</a>.</td></tr><tr><td><strong>Změna stavu zjišťovacího protokolu</strong></td><td>Tlačítka pro další krok, například <strong>Odeslat na schválení</strong>, <strong>Vrátit k opravě</strong>, <strong>Schválit</strong> nebo <strong>Odemknout</strong>. Nabízejí se podle stavu protokolu a vašich kompetencí – viz <a href="/buildary-help-preview/performedworks/contractor_actions">Zadat a schválit soupis</a>.</td></tr></tbody></table><p>Každá dvojice firem má za období vlastní zjišťovací protokol – viz <a href="/buildary-help-preview/performedworks/#zakladni-pojmy">Soupisy provedených prací</a>.</p><h2 id="rekapitulace" tabindex="-1">Rekapitulace <a class="header-anchor" href="#rekapitulace" aria-label="Permalink to &quot;Rekapitulace&quot;">​</a></h2><p>Panel <strong>Rekapitulace</strong> shrnuje částky za stavbu z pohledu vybrané dvojice firem: rozpočet, změny a zamítnuté částky, už vyčerpané částky a navržené a fakturované ceny podle stavu položek.</p><ul><li>Bílá část panelu ukazuje součty za všechna období.</li><li>Barevná část ukazuje součty za období vybrané v záhlaví.</li><li>Ikona domečku znamená, že se sčítají všechny položky stavby. Ikona filtru znamená, že se sčítají jen položky, které odpovídají zapnutému filtru.</li></ul><h2 id="sloupce-tabulky" tabindex="-1">Sloupce tabulky <a class="header-anchor" href="#sloupce-tabulky" aria-label="Permalink to &quot;Sloupce tabulky&quot;">​</a></h2><p>Tabulka ukazuje položky části stavby, kterou máte vybranou v panelu <a href="#struktura-stavby">Struktura stavby</a>. Když zapnete filtr, ukazuje jen položky, které mu odpovídají.</p><table tabindex="0"><thead><tr><th>Skupina sloupců</th><th>Co obsahuje</th></tr></thead><tbody><tr><td><strong>Položka</strong></td><td>Zatržítko pro <a href="#hromadne-operace">hromadné operace</a>, <strong>Číslo</strong>, <strong>Typ</strong> (stavební objekt, část, oddíl, položka), <strong>Kód</strong>, <strong>Popis</strong>, <strong>Číslo smlouvy</strong> a <strong>MJ</strong>. Ikona <strong>i</strong> u popisu otevře <a href="#detail-polozky">detail položky</a>.</td></tr><tr><td><strong>Zbývá</strong></td><td>Kolik z rozpočtu zbývá vyčerpat: <strong>%</strong> (také jako ikona s procentem), <strong>Množství</strong> a <strong>Cena</strong>.</td></tr><tr><td>Vybrané období (v záhlaví skupiny název období a stav protokolu, například <strong>Říjen 2026 – Schvalování</strong>)</td><td>Sloupce pro zadání a schválení čerpání – viz níže.</td></tr><tr><td><strong>Hotovo</strong></td><td>Provedené <strong>Množství</strong> a <strong>Cena</strong> včetně čerpání ve vybraném období.</td></tr><tr><td><strong>Rozpočet</strong></td><td>Celkové množství, jednotková cena a cena položky podle rozpočtu.</td></tr></tbody></table><p><strong>Číslo smlouvy</strong> je vyplněné u rozpočtu načteného z RSV nebo KROS – viz <a href="/buildary-help-preview/performedworks/budget">Načíst rozpočet</a>.</p><h3 id="sloupce-vybraneho-obdobi" tabindex="-1">Sloupce vybraného období <a class="header-anchor" href="#sloupce-vybraneho-obdobi" aria-label="Permalink to &quot;Sloupce vybraného období&quot;">​</a></h3><p>Sloupce této skupiny se zobrazují podle stavu zjišťovacího protokolu a podle vašich kompetencí. Buňky, které smíte upravit, jsou podbarvené žlutě.</p><table tabindex="0"><thead><tr><th>Sloupec</th><th>Kdo ho vyplňuje</th><th>Význam</th></tr></thead><tbody><tr><td><strong>Navržené množství</strong></td><td>zhotovitel (v SPP Podzhotovitele podzhotovitel)</td><td>Množství provedené v období. <strong>Navržená cena</strong> se dopočítá.</td></tr><tr><td><strong>Změna návrhu</strong></td><td>zhotovitel (podzhotovitel)</td><td>Nové množství u položky, kterou schvalující vrátil k opravě.</td></tr><tr><td><strong>Navržená cena</strong></td><td>zhotovitel (podzhotovitel)</td><td>Cena za navržené množství. Místo množství můžete zadat přímo částku.</td></tr><tr><td><strong>Fakturované množství</strong></td><td>stavebník (v SPP Podzhotovitele zhotovitel)</td><td>Množství, které schvalující uznává. Po odeslání na schválení odpovídá navrženému množství.</td></tr><tr><td><strong>Stav položky</strong></td><td>stavebník (zhotovitel)</td><td><strong>Návrh</strong>, <strong>V jednání</strong>, <strong>Schváleno</strong>, <strong>Změna</strong> nebo <strong>Zamítnuto</strong> – viz <a href="/buildary-help-preview/performedworks/contractor_actions#stavy-polozky">Zadat a schválit soupis</a>.</td></tr><tr><td><strong>Fakturovaná cena</strong></td><td>stavebník (zhotovitel)</td><td>Cena za fakturované množství.</td></tr></tbody></table><p>Kdy který sloupec smíte upravit, popisuje <a href="/buildary-help-preview/performedworks/contractor_actions">Zadat a schválit soupis</a>.</p><figure class="shot" style="--w:760px;"><img src="'+p+'" alt="Sloupce období Říjen 2026 ve stavu Schvalování: Navržené množství, Změna návrhu, Navržená cena, Fakturované množství, Stav položky a Fakturovaná cena, za nimi skupina Hotovo" loading="lazy"></figure><h2 id="zadat-mnozstvi" tabindex="-1">Zadat množství <a class="header-anchor" href="#zadat-mnozstvi" aria-label="Permalink to &quot;Zadat množství&quot;">​</a></h2><ol><li>Klikněte do žluté buňky, například ve sloupci <strong>Navržené množství</strong>.</li><li>Napište číslo a potvrďte klávesou Enter. Cena se dopočítá.</li></ol><p>Množství můžete zadat také v procentech z celkového množství položky: za číslo napište <strong>%</strong> nebo <strong>p</strong>, například <code>50%</code> nebo <code>50p</code>. Aplikace procento přepočítá na množství.</p><p>Čerpání více položek najednou zadáte <a href="#hromadne-operace">hromadnými operacemi</a>.</p><h2 id="poznamky-k-polozkam" tabindex="-1">Poznámky k položkám <a class="header-anchor" href="#poznamky-k-polozkam" aria-label="Permalink to &quot;Poznámky k položkám&quot;">​</a></h2><p>Ikonou bubliny v řádku položky zapíšete poznámku k čerpání ve vybraném období, například proč navrhujete jiné množství nebo proč položku vracíte. Oranžová ikona znamená, že položka poznámku má. Poznámky ke všem obdobím najdete v <a href="#detail-polozky">detailu položky</a>.</p><h2 id="detail-polozky" tabindex="-1">Detail položky <a class="header-anchor" href="#detail-polozky" aria-label="Permalink to &quot;Detail položky&quot;">​</a></h2><p>Ikona <strong>i</strong> u popisu položky otevře okno <strong>Detail položky</strong>:</p><ul><li>popis položky, kód, měrnou jednotku a jednotkovou cenu,</li><li>souhrn <strong>Zbývá vyčerpat</strong>, <strong>Vyčerpáno</strong> a <strong>Rozpočet</strong>,</li><li><strong>Historii čerpání</strong> po obdobích – fakturované množství a cenu, kdo a kdy čerpání uzavřel, a poznámky k čerpání.</li></ul><h2 id="struktura-stavby" tabindex="-1">Struktura stavby <a class="header-anchor" href="#struktura-stavby" aria-label="Permalink to &quot;Struktura stavby&quot;">​</a></h2><p>Panel <strong>Struktura stavby</strong> vlevo od tabulky zobrazuje rozpočet jako strom: stavební objekty, části stavby a oddíly. Strom může mít libovolný počet úrovní.</p><ul><li>Kliknutím na úroveň zobrazíte v tabulce jen její položky.</li><li>Více úrovní najednou vyberete s klávesou Ctrl nebo Shift, případně dlouhým stiskem myši.</li><li>U každé úrovně je počet nevyřešených a vyřešených položek ve vybraném období. Podle něj rychle najdete, kde ještě zbývá práce.</li><li>Tlačítka <strong>Rozbalit vše</strong>, <strong>Rozbalit části</strong> a <strong>Sbalit</strong> nad stromem rozbalí nebo sbalí jeho úrovně. Pole pro hledání strom vyfiltruje podle zadaného textu.</li><li>Tlačítkem <strong>Skrýt panel</strong> panel schováte a získáte víc místa pro tabulku.</li></ul><h2 id="hromadne-operace" tabindex="-1">Hromadné operace <a class="header-anchor" href="#hromadne-operace" aria-label="Permalink to &quot;Hromadné operace&quot;">​</a></h2><p>Menu <strong>Hromadné operace</strong> změní najednou všechny zatržené položky v tabulce. Zatržením řádku na vyšší úrovni (například oddílu) označíte všechny jeho položky.</p><table tabindex="0"><thead><tr><th>Operace</th><th>Co udělá</th></tr></thead><tbody><tr><td><strong>Čerpání částkou</strong></td><td>Rozpočítá zadanou částku na označené položky. Nejvýš můžete zadat součet zbývajících cen označených položek. Když jsou mezi označenými kladné i záporné položky, rozpočítá se kladná částka jen na kladné položky a záporná jen na záporné – aplikace vás na to upozorní.</td></tr><tr><td><strong>Čerpání procentem</strong></td><td>U každé označené položky vyčerpá zadané procento z jejího celkového množství. Zadejte jen číslo, bez znaku %. Položku nelze přečerpat: když by procento překročilo zbývající množství, vyčerpá se jen zbytek.</td></tr><tr><td><strong>Změna stavu položky</strong></td><td>Nastaví označeným položkám vybraný stav. Jen když je protokol ve stavu <strong>Schvalování</strong>.</td></tr><tr><td><strong>Smazat čerpání</strong></td><td>Smaže u označených položek všechna zadaná data a vrátí je do výchozího stavu. Jen když je protokol ve stavu <strong>Schvalování</strong>.</td></tr></tbody></table><p>V menu je také hromadné dorovnání čerpání a nákladů: dorovnání nákladů a rozpuštění čerpání do nákladových položek jednotlivých podzhotovitelů. Dorovnat čerpání můžete i přímo na položce rozpočtu.</p><p>Před provedením operace zvolíte, zda označení položek zůstane zachované. Hodí se to, když chcete se stejnými položkami provést další operaci.</p><div class="tip custom-block"><p class="custom-block-title">Zrušit označení</p><p>Klikněte dvakrát na zatržítko v záhlaví sloupce: první kliknutí označí všechny zobrazené položky, druhé označení zruší.</p></div><h2 id="filtrace" tabindex="-1">Filtrace <a class="header-anchor" href="#filtrace" aria-label="Permalink to &quot;Filtrace&quot;">​</a></h2><p>Filtr vyberete v menu <strong>Filtrace</strong>: nejdřív, podle čeho filtrovat, pak v poli <strong>Filtrovat dle</strong> hodnotu, a klikněte na <strong>Filtrovat</strong>. Filtr zrušíte tlačítkem <strong>Vynulovat filtr</strong>.</p><figure class="shot" style="--w:240px;"><img src="'+t+'" alt="Menu Filtrace s výběrem Stav položky, hodnotou Návrh a tlačítky Vynulovat filtr a Filtrovat" loading="lazy"></figure><table tabindex="0"><thead><tr><th>Filtrovat podle</th><th>Hodnoty</th></tr></thead><tbody><tr><td><strong>Stav položky</strong></td><td>Jednotlivé stavy, nebo souhrnně <strong>Otevřené</strong> (Návrh a V jednání – ještě nevyřešené) a <strong>Uzavřené</strong> (Schváleno, Změna a Zamítnuto – vyřešené).</td></tr><tr><td><strong>Čerpání v daném období</strong></td><td><strong>Čerpané</strong> – položky s nenulovým fakturovaným množstvím ve vybraném období, <strong>Nečerpané</strong> – bez fakturovaného množství.</td></tr><tr><td><strong>Čerpání ve všech obdobích</strong></td><td><strong>Čerpané</strong> – s fakturovaným množstvím aspoň v jednom období, <strong>Nečerpané</strong> – bez fakturovaného množství ve všech obdobích, <strong>Zcela vyčerpané</strong> – s nulovým zbývajícím množstvím, <strong>Zbývá čerpat více než</strong> a <strong>Zbývá čerpat méně než</strong> zadané procento množství.</td></tr><tr><td><strong>Číslo smlouvy</strong></td><td>U rozpočtu načteného z RSV nebo KROS.</td></tr></tbody></table><p>Filtr platí pro všechny položky stavby. Proto mění i panel <strong>Struktura stavby</strong>: úrovně bez vyhovujících položek se ve stromu nezobrazí. Filtr se uplatní také v exportech – viz <a href="/buildary-help-preview/performedworks/output_methods">Výstupy soupisů</a>.</p><h2 id="hledat" tabindex="-1">Hledat <a class="header-anchor" href="#hledat" aria-label="Permalink to &quot;Hledat&quot;">​</a></h2><p>Tlačítkem <strong>Hledat</strong> vyhledáte položky, které obsahují zadaný text v kódu nebo popisu.</p><h2 id="zhotovitel-a-podzhotovitel" tabindex="-1">Zhotovitel × podzhotovitel <a class="header-anchor" href="#zhotovitel-a-podzhotovitel" aria-label="Permalink to &quot;Zhotovitel × podzhotovitel {#zhotovitel-a-podzhotovitel}&quot;">​</a></h2><p>Okno <strong>SPP Podzhotovitele</strong> se ovládá stejně jako <strong>SPP Zhotovitele</strong>. Liší se firmami v záhlaví (<strong>Zhotovitel</strong> a <strong>Podzhotovitel</strong>) a položkami: ukazuje jen položky, které mají v rozpočtu vyplněnou kalkulační část s podzhotovitelem – viz <a href="/buildary-help-preview/performedworks/budget#firmy-a-podzhotovitele-v-rozpoctu">Načíst rozpočet</a>. Kdo v něm navrhuje a kdo schvaluje, shrnuje <a href="/buildary-help-preview/performedworks/#u-podzhotovitelu-je-to-jinak">Soupisy provedených prací</a>.</p><figure class="shot" style="--w:760px;"><img src="'+e+'" alt="Okno SPP Podzhotovitele s výběrem zhotovitele Stavby Demo a podzhotovitele Tesařství Horák a položkami oddílu Vodorovné konstrukce" loading="lazy"></figure><h2 id="tisky-a-exporty" tabindex="-1">Tisky a exporty <a class="header-anchor" href="#tisky-a-exporty" aria-label="Permalink to &quot;Tisky a exporty&quot;">​</a></h2><p>Menu <strong>Tisky a exporty</strong> stáhne zjišťovací protokol vybraného období do Excelu nebo PDF – viz <a href="/buildary-help-preview/performedworks/output_methods">Výstupy soupisů</a>.</p>',51)])])}const y=a(d,[["render",i]]);export{g as __pageData,y as default};
